INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('4cbb2ee7f2db47bdb43406b98eb325f5','user_service_agreement','用户服务协议','2026.09','all_user','html','<h2>用户服务协议</h2><p>本协议用于说明幕间平台账号、服务使用和责任边界。注册时一次勾选，后台分别保存各规则的版本和同意时间。</p><h3>一、账号与身份</h3><ol><li>用户应使用本人有效手机号和微信身份注册，并保证提交资料真实有效。</li><li>普通用户、工厂和管理员正式身份互斥；需要切换身份时按平台审核流程办理。</li><li>账号不得出借、转让或用于规避待缴赔付、信用限制及平台审核。</li></ol><h3>二、平台服务</h3><ol><li>平台提供道具浏览、方案、清单、租赁订单、定制购买、履约留证、客服和争议处理能力。</li><li>不同业务对象有独立状态和权限，聊天或线下沟通不能替代系统内的正式订单、退款、索赔和裁决记录。</li></ol><h3>三、用户责任</h3><ol><li>用户应按约定支付费用、核验道具、妥善使用并按时归还。</li><li>存在已生效且未缴清的赔付款时，平台可限制新的租赁支付，但不影响既有订单和退款处理。</li></ol><div class="rule-document-note"><p>完整法律文本由运营在后台维护并发布；本页展示当前产品原型中的核心条款结构。</p></div>','4b56de69fcc272930ea022c41f483255a432b000546ff469c6ac86bee1001adb',1,0,'active','2026-09-02 00:00:00.000',@d2_time,@d2_time);
INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('1ae0be642cae43c2bc02a84cdbd43537','privacy_policy','隐私政策','2026.09','all_user','html','<h2>隐私政策</h2><p>平台仅在提供服务、履约风控和争议处理所需范围内处理个人信息。</p><h3>一、信息范围</h3><ol><li>登录身份、手机号，以及人工实名审核所需姓名、身份证号和证件正反面资料。</li><li>收货地址、订单、支付退款、履约证据、客服案件和评价信用事件。</li><li>工厂入驻资料、联系人信息及履约操作记录。</li></ol><h3>二、使用目的</h3><ol><li>完成登录注册、实名认证、下单支付、履约交付、退款结算和客服处理。</li><li>识别越权访问、重复提交、支付风险和争议责任。</li></ol><h3>三、保存与安全</h3><ol><li>姓名和完整身份证号以可还原密文保存，证件正反面私有存储；有审核权限的管理员可查看完整资料并留审计，工厂及用户接口返回脱敏信息。人工审核不等于外部联网核验。</li><li>当前设计暂不设置实名资料自动清理任务；保存期限及用户权利须在上线前完成合规审查。订单、资金、证据和审计记录按业务及合规要求保存。</li></ol><div class="rule-document-note"><p>微信客服中的即时聊天由微信渠道承载；平台只保存会话关系、必要摘要和正式处理动作。</p></div>','c80c68947b60edbb026113f9ab4f9260eeae1c0885d4ccb9d080d6bd19f0f5f2',1,0,'active','2026-09-02 00:00:00.000',@d2_time,@d2_time);
INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('84e561caf70341e6b6b170513080ac02','rental_transaction_rule','租赁交易规则','2026.09','all_user','html','<h2>租赁交易规则</h2><p>方案用于提案，清单用于绑定租期并结算。支付成功后按工厂生成独立租赁订单。</p><h3>一、支付与接单</h3><ol><li>提交清单后进入十分钟支付短锁；支付失败、取消或超时不生成用户可见订单，清单回到选品中。</li><li>支付成功后每个工厂订单独立接单。工厂应在两小时内处理，某个工厂拒绝不影响其他订单。</li></ol><h3>二、取消与延期</h3><ol><li>工厂接单前用户取消可全额退款；接单后按页面展示的取消规则计算租金扣除，押金原则上不作为普通取消违约金。</li><li>延期需在规则时限内申请，经工厂确认并完成延期支付后，才更新订单应归还日期和库存占用日期。</li></ol><h3>三、完成与异常</h3><ol><li>收货、使用、归还和核验按订单阶段开放入口，异常先留证，再由客服或仲裁形成正式结果。</li><li>订单资金结清且无处理中争议后进入工厂结算；用户评价不阻塞结算。</li></ol>','4f923d818bf0e0d601efe054c5ba7c51fcad910a261eb087e74a3148b13293a9',1,0,'active','2026-09-02 00:00:00.000',@d2_time,@d2_time);
INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('dfdef4e8ae2b49e5b1b1b3d3c9e3efd5','deposit_compensation_rule','押金与赔付规则','2026.09','all_user','html','<h2>押金与赔付规则</h2><p>押金是真实支付到平台的履约保障金，不计入平台佣金基数。</p><h3>一、押金处理</h3><ol><li>无异常完成归还核验后，剩余押金原路退回；工厂逾期不处理时，系统可按规则自动无异常关闭，管理员也可强制结束。</li><li>索赔、仲裁或平台介入期间，争议金额暂不释放，其余可退金额按已确认结果处理。</li></ol><h3>二、扣款与赔付</h3><ol><li>工厂索赔必须提交原因和证据，经管理员审核后发送用户确认；用户申诉后进入人工裁决。</li><li>已确认损失先从该订单剩余押金中扣除，赔付给工厂的押金不参与平台抽佣。</li><li>损失超过剩余押金时，押金可全部扣除并形成待缴赔付款；用户缴清前不得提交新的租赁支付。</li></ol><h3>三、资金可追溯</h3><ol><li>每笔扣款、退款和待缴赔付都关联原订单、原支付单、证据或裁决结果。</li><li>同一支付单可以发生多次退款，但累计退款不得超过可退现金上限。</li></ol>','4c4c9cbc341903d8ae9db61c33b28e38394e02570772fba577d16e0b6be66a1b',1,0,'active','2026-09-02 00:00:00.000',@d2_time,@d2_time);
INSERT INTO platform_rule_document (id,rule_code,rule_title,rule_version,rule_scope,content_type,content_text,content_hash,is_required,force_reaccept,rule_status,effective_at,created_at,updated_at) VALUES ('0d7945378c6943cb9bdaa7ccabbd926b','logistics_transport_rule','物流与运输规则','2026.09','all_user','html','<h2>物流与运输规则</h2><p>用户在结算前按工厂选择去程和回程方式，并查看平台运输价格依据。</p><h3>一、运输方式</h3><ol><li>去程支持工厂配送、工厂协助叫车和用户自提；回程支持用户送回和工厂取回。</li><li>工厂配送和工厂取回可预收运费；协助叫车按第三方实际费用处理；用户自提或送回由用户自行安排。</li></ol><h3>二、价格与差额</h3><ol><li>平台根据道具体积、重量、车型区间和地图驾车距离估算运费，并在支付时冻结计算快照。</li><li>去程、回程分别记账，用户端按同一订单的运费暂收池结算净差额；运费不参与平台佣金。</li></ol><h3>三、运输要求</h3><ol><li>易碎、异形或高价值道具的包装与运输要求在结算、出库和归还页面以醒目方式提示。</li><li>运输要求是责任判断依据，不限制用户可选择的运输方式；未按要求包装、搬运或交接造成损失的，应按证据承担责任。</li></ol>','8d2ce42244d40cc69789e77601706a2f266bc895870fd86315c5ae49bc75e7ea',1,0,'active','2026-09-02 00:00:00.000',@d2_time,@d2_time);
